dog.speak()

class User:
    def __init__(self, name):
        self._name = name

    @property
    def name(self):
        return self._name

    @name.setter
    def name(self, value):
        if value == "":
            raise ValueError("名前は空にできません")
        self._name = value

user = User("田中")
print(user.name)
user.name = "鈴木"

